function msg(string $m):void{$_SESSION['msg']=$m;}
$me=$_SESSION['user']??null;$page=$_GET['page']??($me?'dashboard':'login');$notice=$_SESSION['msg']??'';unset($_SESSION['msg']);$admin=$me&&in_array($me['role'],['school_admin','platform_admin'],true);$sid=(int)($me['school_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf();$act=$_POST['action']??'';
 try{
  if($act==='register'){$name=trim($_POST['school']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10)throw new RuntimeException('Enter a school name, valid email, and password of at least 10 characters.');$db->beginTransaction();$q=$db->prepare("INSERT INTO schools(name,status) VALUES(?,'pending')");$q->execute([$name]);$sid=(int)$db->lastInsertId();$q=$db->prepare("INSERT INTO users(school_id,name,email,password_hash,role) VALUES(?,?,?,?, 'school_admin')");$q->execute([$sid,trim($_POST['name']??'')?:'Michael Ron Dimaano',$email,password_hash($pass,PASSWORD_DEFAULT)]);$db->commit();msg('Registration received. A platform administrator must approve the school.');go('login');}
  if($act==='login'){$ip=$_SERVER['REMOTE_ADDR']??'unknown';$q=$db->prepare('SELECT COUNT(*) FROM login_attempts WHERE ip_address=? AND attempted_at>DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$q->execute([$ip]);if($q->fetchColumn()>=8)throw new RuntimeException('Too many attempts. Try again in 15 minutes.');$q=$db->prepare('SELECT u.*,s.name school_name,s.status school_status FROM users u LEFT JOIN schools s ON s.id=u.school_id WHERE u.email=? AND u.active=1');$q->execute([strtolower(trim($_POST['email']??''))]);$x=$q->fetch();if(!$x||!password_verify($_POST['password']??'',$x['password_hash'])){$db->prepare('INSERT INTO login_attempts(ip_address) VALUES(?)')->execute([$ip]);throw new RuntimeException('Email or password is incorrect.');}if($x['role']!=='platform_admin'&&$x['school_status']!=='active')throw new RuntimeException('This school is not active yet.');unset($x['password_hash']);session_regenerate_id(true);$_SESSION['user']=$x;go();}
  if($act==='logout'){session_destroy();go('login');}
  if(!$me)go('login');
  if($act==='profile'){$name=trim($_POST['name']??'');if(!$name)throw new RuntimeException('Name is required.');$avatar=$me['avatar_path']??null;if(!empty($_FILES['avatar']['name'])){$f=$_FILES['avatar'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>3145728)throw new RuntimeException('Photo must be under 3 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext||!getimagesize($f['tmp_name']))throw new RuntimeException('Choose a JPG, PNG, or WebP image.');$avatar='avatar_'.(int)$me['id'].'_'.bin2hex(random_bytes(5)).'.'.$ext;$dir=dirname(__DIR__).'/storage/avatars';if(!is_dir($dir))mkdir($dir,0750,true);move_uploaded_file($f['tmp_name'],$dir.'/'.$avatar);}$db->prepare('UPDATE users SET name=?,avatar_path=? WHERE id=?')->execute([$name,$avatar,$me['id']]);$_SESSION['user']['name']=$name;$_SESSION['user']['avatar_path']=$avatar;msg('Profile saved.');go('profile');}
  if($act==='password'){$q=$db->prepare('SELECT password_hash FROM users WHERE id=?');$q->execute([$me['id']]);if(!password_verify($_POST['current']??'',$q->fetchColumn()))throw new RuntimeException('Current password is incorrect.');$p=$_POST['password']??'';if(strlen($p)<10)throw new RuntimeException('Use at least 10 characters.');$db->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($p,PASSWORD_DEFAULT),$me['id']]);msg('Password changed.');go('profile');}
  if($act==='leave'){$a=$_POST['start']??'';$b=$_POST['end']??'';$r=trim($_POST['reason']??'');if(!$a||!$b||$b<$a||!$r)throw new RuntimeException('Choose valid dates and enter a reason.');$db->prepare('INSERT INTO leave_requests(school_id,user_id,start_date,end_date,reason) VALUES(?,?,?,?,?)')->execute([$sid,$me['id'],$a,$b,$r]);$db->prepare("INSERT INTO notifications(user_id,school_id,message) SELECT id,school_id,'A new leave request needs review.' FROM users WHERE school_id=? AND role='school_admin'")->execute([$sid]);msg('Leave request sent.');go('leaves');}
