  if($act==='decision'&&$admin){$id=(int)$_POST['id'];$status=$_POST['status']==='approved'?'approved':'rejected';$q=$db->prepare("SELECT user_id FROM leave_requests WHERE id=? AND school_id=? AND status='pending'");$q->execute([$id,$sid]);$owner=$q->fetchColumn();if(!$owner)throw new RuntimeException('Request not found.');$db->prepare('UPDATE leave_requests SET status=?,admin_remark=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND school_id=?')->execute([$status,trim($_POST['remark']??''),$me['id'],$id,$sid]);$db->prepare('INSERT INTO leave_approvals(leave_id,school_id,reviewer_id,decision,remark) VALUES(?,?,?,?,?)')->execute([$id,$sid,$me['id'],$status,trim($_POST['remark']??'')]);$db->prepare('INSERT INTO notifications(user_id,school_id,message) VALUES(?,?,?)')->execute([$owner,$sid,"Your leave request was $status."]);msg('Decision saved.');go('leaves');}
  if($act==='feedback'){$s=trim($_POST['subject']??'');$m=trim($_POST['message']??'');if(!$s||!$m)throw new RuntimeException('Subject and message are required.');$db->prepare('INSERT INTO feedback(school_id,user_id,category,subject,message) VALUES(?,?,?,?,?)')->execute([$sid,$me['id'],$_POST['category']??'General Feedback',$s,$m]);msg('Feedback submitted.');go('feedback');}
