  if($act==='school'&&$admin){$n=trim($_POST['name']??'');if(!$n)throw new RuntimeException('School name is required.');$db->prepare('UPDATE schools SET name=? WHERE id=?')->execute([$n,$sid]);$_SESSION['user']['school_name']=$n;msg('School details saved.');go('school');}
  if($act==='school_review'&&$me['role']==='platform_admin'){$st=$_POST['status']??'';if(!in_array($st,['active','rejected','suspended'],true))throw new RuntimeException('Invalid status.');$db->prepare('UPDATE schools SET status=? WHERE id=?')->execute([$st,(int)$_POST['id']]);msg('School status updated.');go('schools');}
  if($act==='user'&&$admin){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$role=$_POST['role']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,['teacher','student'],true))throw new RuntimeException('Check name, email, and role.');if($id)$db->prepare("UPDATE users SET name=?,email=?,role=?,active=? WHERE id=? AND school_id=? AND role IN ('teacher','student')")->execute([$name,$email,$role,isset($_POST['active'])?1:0,$id,$sid]);else{$p=$_POST['password']??'';if(strlen($p)<10)throw new RuntimeException('Initial password must be at least 10 characters.');$db->prepare('INSERT INTO users(school_id,name,email,password_hash,role) VALUES(?,?,?,?,?)')->execute([$sid,$name,$email,password_hash($p,PASSWORD_DEFAULT),$role]);}msg('Account saved.');go('users');}
 }catch(Throwable $ex){if($db->inTransaction())$db->rollBack();msg($ex instanceof PDOException&&$ex->getCode()==='23000'?'That email is already registered.':$ex->getMessage());go($page);}
}
$rows=[];$stats=[];
if($me){if($page==='dashboard'){if($me['role']==='platform_admin'){$stats=$db->query("SELECT COUNT(*) total,SUM(status='pending') pending,SUM(status='active') approved FROM schools")->fetch();$q=$db->query('SELECT * FROM schools ORDER BY created_at DESC LIMIT 8');$rows=$q->fetchAll();}else{$q=$db->prepare("SELECT COUNT(*) total,SUM(status='pending') pending,SUM(status='approved') approved,SUM(status='rejected') rejected FROM leave_requests WHERE school_id=?");$q->execute([$sid]);$stats=$q->fetch();$q=$db->prepare('SELECT l.*,u.name person,u.role FROM leave_requests l JOIN users u ON u.id=l.user_id WHERE l.school_id=?'.($admin?'':' AND l.user_id=?').' ORDER BY l.created_at DESC LIMIT 8');$q->execute($admin?[$sid]:[$sid,$me['id']]);$rows=$q->fetchAll();}}
elseif($page==='leaves'){$q=$db->prepare('SELECT l.*,u.name person,u.role FROM leave_requests l JOIN users u ON u.id=l.user_id WHERE l.school_id=?'.($admin?'':' AND l.user_id=?').' ORDER BY l.created_at DESC');$q->execute($admin?[$sid]:[$sid,$me['id']]);$rows=$q->fetchAll();}
elseif($page==='feedback'){$q=$db->prepare('SELECT f.*,u.name person FROM feedback f JOIN users u ON u.id=f.user_id WHERE f.school_id=?'.($admin?'':' AND f.user_id=?').' ORDER BY f.created_at DESC');$q->execute($admin?[$sid]:[$sid,$me['id']]);$rows=$q->fetchAll();}
