elseif($page==='attendance'){$month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month))$month=date('Y-m');$first=DateTimeImmutable::createFromFormat('!Y-m-d',$month.'-01',new DateTimeZone('Asia/Manila'));$last=$first->modify('last day of this month');$q=$db->prepare('SELECT * FROM attendance_records WHERE school_id=? AND user_id=? AND attendance_date BETWEEN ? AND ? ORDER BY attendance_date');$q->execute([$sid,$me['id'],$first->format('Y-m-d'),$last->format('Y-m-d')]);$rows=$q->fetchAll();}
elseif($page==='schools'&&$me['role']==='platform_admin')$rows=$db->query('SELECT s.*,(SELECT COUNT(*) FROM users WHERE school_id=s.id) users FROM schools s ORDER BY created_at DESC')->fetchAll();
