ent">Absent</option><option value="leave">Leave</option><option value="holiday">Holiday</option></select></label><label>Time in <input type="time" name="time_in"></label><label>Time out <input type="time" name="time_out"></label><button class="btn">Save DTR</button></form></section><section class="card section tablebox"><table><thead><tr><th>Date</th><th>Day</th><th>Time in</th><th>Time out</th><th>Total hours</th><th>Status</th><th>Remarks</th></tr></thead><tbody><?php for($day=$first;$day<=$last;$day=$day->modify('+1 day')):$key=$day->format('Y-m-d');$rec=$byDate[$key]??null;$hours='—';if($rec&&$rec['time_in']&&$rec['time_out']){$minutes=(strtotime($rec['time_out'])-strtotime($rec['time_in']))/60;if($minutes>=0)$hours=number_format($minutes/60,2).' h';}?><tr><td><?=e($day->format('M j, Y'))?></td><td><?=e($day->format('l'))?></td><td><?=e($rec['time_in']?substr($rec['time_in'],0,5):'—')?></td><td><?=e($rec['time_out']?substr($rec['time_out'],0,5):'—')?></td><td><?=e($hours)?></td><td><?php if($rec):?><span class="badge <?=e($rec['status'])?>"><?=e(ucfirst($rec['status']))?></span><?php else:?><span class="badge">Not recorded</span><?php endif;?></td><td><?=e($rec['remarks']??'')?></td></tr><?php endfor;?></tbody></table></section>
